package com.logiplatform.service;
import com.logiplatform.dto.PublicPortalDtos.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class PublicPortalService { private final JdbcTemplate db; public PublicPortalService(@Qualifier("authJdbcTemplate")JdbcTemplate db){this.db=db;}
 public PortalView find(UUID token){try{PortalView base=db.queryForObject("SELECT s.id,s.reference_code,s.origin_address,s.destination_address,s.status,s.transport_mode,s.client_name,s.eta,s.amount_billed_to_client,s.currency,i.invoice_no,i.amount_paid,i.due_date FROM shipments s LEFT JOIN commercial_invoices i ON i.shipment_id=s.id WHERE s.tracking_token=? ORDER BY i.issue_date DESC NULLS LAST LIMIT 1",(rs,n)->new PortalView(rs.getObject("id",UUID.class),rs.getString("reference_code"),rs.getString("origin_address"),rs.getString("destination_address"),rs.getString("status"),rs.getString("transport_mode"),rs.getString("client_name"),rs.getTimestamp("eta")==null?null:rs.getTimestamp("eta").toInstant(),rs.getBigDecimal("amount_billed_to_client"),rs.getString("currency"),rs.getString("invoice_no"),rs.getBigDecimal("amount_paid"),rs.getDate("due_date")==null?null:rs.getDate("due_date").toLocalDate(),new ListItem[0])); ListItem[] events=db.query("SELECT e.event_type,e.location,e.notes,e.occurred_at FROM shipment_tracking_events e JOIN shipments s ON s.id=e.shipment_id WHERE s.tracking_token=? ORDER BY e.occurred_at ASC",(rs,n)->new ListItem(rs.getString("event_type"),rs.getString("location"),rs.getString("notes"),rs.getTimestamp("occurred_at").toInstant()),token).toArray(ListItem[]::new); return new PortalView(base.shipmentId(),base.referenceCode(),base.origin(),base.destination(),base.status(),base.transportMode(),base.clientName(),base.eta(),base.billedAmount(),base.currency(),base.invoiceNo(),base.amountPaid(),base.dueDate(),events);}catch(Exception e){if(e instanceof ResponseStatusException x)throw x;throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Portal link not found");}}
}
